/*
 * The drop-glue differential harness. `glue_cases.h` (generated by tests/support/glue.rs) holds
 * a descriptor per corpus layout, typed object graphs and the emitted entries that release a
 * root through compiled glue. Every graph is built twice in a fresh context and released once by
 * the runtime's step-program walk (hirsel_rt_v2_release) and once by its entry. A run's trace is
 * its status, the failure chain, every finalizer and handle close in order, and for each block
 * whether it was freed and which block its slab's free list links it to: the block of that slab
 * freed just before it, so the links are the free order. The two traces must be equal.
 */
#include <inttypes.h>
#include <pthread.h>
#include <stdarg.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "hirsel_rt_v2.h"

typedef hirsel_rt_v2_ctx ctx_t;
typedef hirsel_rt_v2_header block_t;
/* `call_<entry>` (generated by `hirsel_llvm::c_call`): an entry of `fn(take Box[T], i64) -> i64`
 * through its ABI v1 signature, the i64 result through its pointer. */
typedef uint8_t (*entry_t)(ctx_t *, void *, void *, int64_t);

struct reloc {
    uint32_t offset, target;
};
struct spec {
    const hirsel_rt_v2_layout *layout;
    uint32_t size, align, held;
    const uint8_t *bytes;
    const struct reloc *relocs;
    uint32_t reloc_count;
};
struct scenario {
    const char *name;
    entry_t entry;
    const struct spec *blocks;
    uint32_t count;
};

static uint8_t fin_log(ctx_t *ctx, void *value, uint64_t anchor);
#include "glue_cases.h"

static char *trace;
static size_t trace_len, trace_cap;

static void say(const char *format, ...) {
    for (;;) {
        va_list arguments;
        va_start(arguments, format);
        int n = vsnprintf(trace + trace_len, trace_cap - trace_len, format, arguments);
        va_end(arguments);
        if ((size_t)n < trace_cap - trace_len) {
            trace_len += (size_t)n;
            return;
        }
        trace_cap = (trace_cap + (size_t)n) * 2;
        trace = realloc(trace, trace_cap);
        if (!trace) abort();
    }
}

static const struct scenario *current;
static block_t **blocks;
static unsigned events, fail_every;

static uint8_t *payload_of(uint32_t index) { return hirsel_rt_v2_payload(blocks[index]); }

/* Every `fail_every`th finalizer or close fails with its own rule. */
static uint8_t event(ctx_t *ctx, uint64_t anchor) {
    events++;
    if (fail_every == 0 || events % fail_every != 0) return 0;
    hirsel_rt_v2_failure_begin(ctx, 1, 100 + events, anchor);
    return 1;
}

static uint8_t fin_log(ctx_t *ctx, void *value, uint64_t anchor) {
    for (uint32_t i = 0; i < current->count; i++) {
        uint8_t *start = payload_of(i);
        uint32_t size = current->blocks[i].size ? current->blocks[i].size : 1;
        if ((uint8_t *)value >= start && (uint8_t *)value < start + size) {
            say("finalize b%u+%u\n", i, (unsigned)((uint8_t *)value - start));
            return event(ctx, anchor);
        }
    }
    say("finalize ?\n");
    return event(ctx, anchor);
}

static uint8_t close_log(ctx_t *ctx, uint64_t handle, uint64_t anchor) {
    say("close %" PRIu64 "\n", handle);
    return event(ctx, anchor);
}

static uint64_t live_blocks(ctx_t *ctx) {
    hirsel_rt_v2_stats stats;
    hirsel_rt_v2_ctx_stats(ctx, &stats);
    return stats.live_blocks;
}

static ctx_t *context(uint32_t flags) {
    hirsel_rt_v2_config config;
    memset(&config, 0, sizeof config);
    config.abi_version = HIRSEL_RT_V2_ABI_VERSION;
    config.flags = flags;
    config.close_handle = close_log;
    ctx_t *ctx;
    if (hirsel_rt_v2_ctx_create(&config, &ctx) != HIRSEL_RT_V2_LAUNCH_OK) abort();
    return ctx;
}

static void say_failures(ctx_t *ctx) {
    hirsel_rt_v2_failure failure;
    if (!hirsel_rt_v2_failure_primary(ctx, &failure)) return;
    say("primary %u %u\n", failure.kind, failure.rule);
    uint64_t causes = hirsel_rt_v2_failure_cause_count(ctx);
    for (uint64_t i = 0; i < causes; i++) {
        if (hirsel_rt_v2_failure_cause(ctx, i, &failure)) say("cause %u %u\n", failure.kind, failure.rule);
    }
    hirsel_rt_v2_failure_clear(ctx);
}

/* Build `scenario`'s graph, release its root by the walk or by its entry, and leave the trace. */
static void run(const struct scenario *scenario, uint32_t flags, unsigned failing, int glue) {
    ctx_t *ctx = context(flags);
    uint32_t n = scenario->count;
    current = scenario;
    blocks = calloc(n, sizeof *blocks);
    uint64_t *holders = calloc(n, sizeof *holders);
    if (!blocks || !holders) abort();
    for (uint32_t i = 0; i < n; i++) {
        const struct spec *spec = &scenario->blocks[i];
        blocks[i] = hirsel_rt_v2_alloc(ctx, hirsel_fixture_index(spec->layout), spec->size ? spec->size : 1, spec->align,
                                       HIRSEL_RT_V2_DOMAIN_HEAP, 0);
        if (spec->size) memcpy(payload_of(i), spec->bytes, spec->size);
        holders[i] = spec->held;
    }
    holders[0] += 1;
    for (uint32_t i = 0; i < n; i++) {
        const struct spec *spec = &scenario->blocks[i];
        for (uint32_t r = 0; r < spec->reloc_count; r++) {
            memcpy(payload_of(i) + spec->relocs[r].offset, &blocks[spec->relocs[r].target], sizeof(block_t *));
            holders[spec->relocs[r].target]++;
        }
    }
    for (uint32_t i = 0; i < n; i++) blocks[i]->count = holders[i];
    trace_len = 0;
    events = 0;
    fail_every = failing;
    int64_t result = 0;
    uint8_t status = glue ? scenario->entry(ctx, &result, blocks[0], 0)
                          : hirsel_rt_v2_release(ctx, blocks[0], blocks[0]->descriptor & 0x1fffffffu, NULL, 7);
    say("status %u\n", status);
    say_failures(ctx);
    for (uint32_t i = 0; i < n; i++) {
        /* A large block's storage went back to the host. */
        if (scenario->blocks[i].size > HIRSEL_RT_V2_SMALL_MAX) {
            say("b%u large\n", i);
            continue;
        }
        block_t *previous;
        memcpy(&previous, blocks[i], sizeof(uintptr_t));
        uint32_t j = 0;
        while (j < n && blocks[j] != previous) j++;
        if (previous != NULL && j == n) {
            say("b%u live count %u\n", i, blocks[i]->count);
            continue;
        }
        say("b%u free after ", i);
        if (j < n) say("b%u\n", j);
        else say("-\n");
    }
    say("live %" PRIu64 "\n", live_blocks(ctx));
    /* The harness's own credits go through the walk, in both runs. */
    fail_every = 0;
    for (uint32_t i = 0; i < n; i++) {
        for (uint32_t h = 0; h < scenario->blocks[i].held; h++) {
            hirsel_rt_v2_release(ctx, blocks[i], blocks[i]->descriptor & 0x1fffffffu, NULL, 7);
        }
    }
    hirsel_rt_v2_failure_clear(ctx);
    say("left %" PRIu64 "\n", live_blocks(ctx));
    free(blocks);
    free(holders);
    hirsel_rt_v2_ctx_destroy(ctx);
}

/* A million-link chain released through its entry on a small stack: past its budget of nested
 * frames the glue hands the rest to the runtime's worklist. */
#define DEEP_LINKS 1000000
static uint32_t deep_flags;
static void *deep(void *unused) {
    (void)unused;
    ctx_t *ctx = context(deep_flags);
    block_t *head = NULL;
    for (uint32_t i = 0; i <= DEEP_LINKS; i++) {
        block_t *node = hirsel_rt_v2_alloc(ctx, hirsel_fixture_index(CHAIN_LAYOUT), CHAIN_SIZE, CHAIN_ALIGN, HIRSEL_RT_V2_DOMAIN_HEAP, 0);
        uint8_t *payload = hirsel_rt_v2_payload(node);
        memset(payload, 0, CHAIN_SIZE);
        if (head) memcpy(payload + CHAIN_NEXT, &head, sizeof head);
        head = node;
    }
    int64_t result = 0;
    uint8_t status = CHAIN_ENTRY(ctx, &result, head, 0);
    printf("deep chain status %u live %" PRIu64 "\n", status, live_blocks(ctx));
    hirsel_rt_v2_ctx_destroy(ctx);
    return NULL;
}

int main(void) {
    static const uint32_t modes[] = {HIRSEL_RT_V2_CONFIG_DIAGNOSTIC, 0};
    static const unsigned failing[] = {0, 1, 3};
    unsigned runs = 0, differing = 0;
    for (size_t s = 0; s < sizeof scenarios / sizeof scenarios[0]; s++) {
        for (size_t m = 0; m < 2; m++) {
            for (size_t f = 0; f < 3; f++) {
                run(&scenarios[s], modes[m], failing[f], 0);
                char *walk = malloc(trace_len + 1);
                if (!walk) abort();
                memcpy(walk, trace, trace_len + 1);
                run(&scenarios[s], modes[m], failing[f], 1);
                runs++;
                if (strcmp(walk, trace) != 0) {
                    differing++;
                    printf("DIFFERENT %s mode %u failing %u\nwalk:\n%sglue:\n%s", scenarios[s].name,
                           (unsigned)modes[m], failing[f], walk, trace);
                }
                /* The production traces are shown, for the test to read. */
                if (modes[m] == 0) printf("== %s failing %u\n%s", scenarios[s].name, failing[f], trace);
                free(walk);
            }
        }
    }
    printf("runs %u differing %u\n", runs, differing);
    for (size_t m = 0; m < 2; m++) {
        deep_flags = modes[m];
        pthread_attr_t attributes;
        pthread_t thread;
        if (pthread_attr_init(&attributes) != 0 || pthread_attr_setstacksize(&attributes, 128 * 1024) != 0) abort();
        if (pthread_create(&thread, &attributes, deep, NULL) != 0) abort();
        pthread_join(thread, NULL);
    }
    return 0;
}
